    final String[] tmp = translateCommandline(line);
    final CommandLine cl = new CommandLine(tmp[0]);
    cl.setSubstitutionMap(substitutionMap);
    for (int i = 1;
    i < tmp.length;
    i++)
    {
        cl.addArgument(tmp[i]);
    }
    return cl;
}
