private AbstractPhotometricInterpreter getPhotometricInterpreter(final TiffDirectory directory, final int photometricInterpretation, final int bitsPerPixel, final int[] bitsPerSample, final int predictor, final int samplesPerPixel, final int width, final int height) throws ImagingException  {
    switch (photometricInterpretation)
    {
        case 0: case 1: final boolean invert = photometricInterpretation == 0;
        return new PhotometricInterpreterBiLevel(samplesPerPixel, bitsPerSample, predictor, width, height, invert);
        case 3:
        {
            // Palette final int[] colorMap = directory.findField(TiffTagConstants.TIFF_TAG_COLOR_MAP, true).getIntArrayValue();
            final int expectedColormapSize = 3 * (1 << bitsPerPixel);
            if (colorMap.length != expectedColormapSize)
            {
                throw new ImagingException("Tiff: fColorMap.length (" + colorMap.length + ") != expectedColormapSize (" + expectedColormapSize + ")");
            }
            return new PhotometricInterpreterPalette(samplesPerPixel, bitsPerSample, predictor, width, height, colorMap);
        }
        case 2: // RGB return new PhotometricInterpreterRgb(samplesPerPixel, bitsPerSample, predictor, width, height);
        case 5: // CMYK return new PhotometricInterpreterCmyk(samplesPerPixel, bitsPerSample, predictor, width, height);
