    }
    BinaryFunctions.skipBytes(is, offsetToFirstIFD - 8, "Not a Valid TIFF File: couldn't find IFDs");
    return new TiffHeader(byteOrder, tiffVersion, offsetToFirstIFD, bigTiff);
