        }
        final ByteArrayInputStream bais = new ByteArrayInputStream(compressed);
        final InflaterInputStream iis = new InflaterInputStream(bais);
        final AbstractScanExpediter abstractScanExpediter;
        switch (pngChunkIHDR.getInterlaceMethod())
        {
            case NONE: abstractScanExpediter = new ScanExpediterSimple(width, height, iis, result, pngColorType, bitDepth, bitsPerPixel, pngChunkPLTE, gammaCorrection, abstractTransparencyFilter);
            break;
            case ADAM7: abstractScanExpediter = new ScanExpediterInterlaced(width, height, iis, result, pngColorType, bitDepth, bitsPerPixel, pngChunkPLTE, gammaCorrection, abstractTransparencyFilter);
            break;
            default: throw new ImagingException("Unknown InterlaceMethod: " + pngChunkIHDR.getInterlaceMethod());
