private JFIFPieces analyzeJfif(final ByteSource byteSource) throws ImagingException, IOException  {
    final List<JFIFPiece> pieces = new ArrayList<>();
    final List<JFIFPiece> exifPieces = new ArrayList<>();
    final JpegUtils.Visitor visitor = new JpegUtils.Visitor()
    {
        // return false to exit before reading image data. @Override public boolean beginSos()
        {
            return true;
        }
        // return false to exit traversal. @Override public boolean visitSegment(final int marker, final byte[] markerBytes, final int markerLength, final byte[] markerLengthBytes, final byte[] segmentData) throws // ImageWriteException, ImagingException, IOException
        {
            if (marker != JpegConstants.JPEG_APP1_MARKER || !JpegConstants.EXIF_IDENTIFIER_CODE.isStartOf(segmentData))
            {
                pieces.add(new JFIFPieceSegment(marker, markerBytes, markerLengthBytes, segmentData));
            }
            else
            {
                final JFIFPiece piece = new JFIFPieceSegmentExif(marker, markerBytes, markerLengthBytes, segmentData);
                pieces.add(piece);
                exifPieces.add(piece);
            }
            return true;
        }
        @Override public void visitSos(final int marker, final byte[] markerBytes, final byte[] imageData)
        {
            pieces.add(new JFIFPieceImageData(markerBytes, imageData));
        }
    }
    ;
    new JpegUtils().traverseJfif(byteSource, visitor);
