void test1BPPIconMaskVersus8BPPMask() throws Exception  {
    final int foreground = 0xff000000;
    final int background = 0xff000000;
    try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
    AbstractBinaryOutputStream bos = AbstractBinaryOutputStream.bigEndian(baos))
    {
        bos.write4Bytes(IcnsImageParser.ICNS_MAGIC);
        bos.write4Bytes(4 + 4 + 4 + 4 + 2 * 16 * 16 / 8 + 4 + 4 + 16 * 16);
        bos.write4Bytes(IcnsType.ICNS_16x16_1BIT_IMAGE_AND_MASK.getType());
        bos.write4Bytes(4 + 4 + 2 * 16 * 16 / 8);
        // 1 BPP image - all black for (int y = 0;
        y < 16;
        y++)
        {
            bos.write(0xff);
            bos.write(0xff);
        }
        // 1 BPP mask - all opaque for (int y = 0;
        y < 16;
        y++)
        {
            bos.write(0xff);
            bos.write(0xff);
        }
        // 8 BPP alpha mask - partially transparent bos.write4Bytes(IcnsType.ICNS_16x16_8BIT_MASK.getType());
        bos.write4Bytes(4 + 4 + 16 * 16);
        for (int y = 0;
        y < 16;
        y++)
        {
            for (int x = 0;
            x < 16;
            x++)
            {
                if (IMAGE[y][x] != 0)
                {
                    bos.write(0xff);
                }
                else
                {
                    bos.write(0x00);
                }
            }
        }
        bos.flush();
        writeAndReadImageData("1bpp-image-mask-versus-8bpp-mask", baos.toByteArray(), foreground, background);
    }
}
