private byte[] cleanImage(final File imageWithExif) throws ImagingException, ImagingException, IOException  {
    // Windows doesn't show XP tags if same-meaning tags exist in IPTC or XMP. Remove them: final ByteArrayOutputStream noXmp = new ByteArrayOutputStream();
    new JpegXmpRewriter().removeXmpXml(imageWithExif, noXmp);
    final ByteArrayOutputStream noXmpNoIptc = new ByteArrayOutputStream();
    new JpegIptcRewriter().removeIptc(noXmp.toByteArray(), noXmpNoIptc);
    return noXmpNoIptc.toByteArray();
}
