public String[] getValue(final ByteOrder byteOrder, final byte[] bytes)  {
    int nullCount = 0;
    for (int i = 0;
    i < bytes.length - 1;
    i++)
    {
        if (bytes[i] == 0)
        {
            nullCount++;
        }
    }
    final String[] strings = Allocator.array(nullCount + 1, String[]::new, 24);
    int stringsAdded = 0;
    strings[0] = "";
    // if we have a 0 length string int nextStringPos = 0;
    // According to the Exiftool FAQ, [BROKEN URL] http://www.metadataworkinggroup.org // specifies that the TIFF ASCII fields are actually UTF-8. // Exiftool however allows you to configure the charset used. for (int i = 0;
    i < bytes.length;
    i++)
    {
        if (bytes[i] == 0)
        {
            final String string = new String(bytes, nextStringPos, i - nextStringPos, StandardCharsets.UTF_8);
            strings[stringsAdded++] = string;
            nextStringPos = i + 1;
        }
    }
    if (nextStringPos < bytes.length)
    {
        // Buggy file, string wasn't null terminated final String string = new String(bytes, nextStringPos, bytes.length - nextStringPos, StandardCharsets.UTF_8);
        strings[stringsAdded++] = string;
    }
    return strings;
}
