        standardTiff = true;
        entryMaxValueLength = ENTRY_MAX_VALUE_LENGTH;
        offsetToFirstIFD = 0xFFFFffffL & BinaryFunctions.read4Bytes("offsetToFirstIFD", is, "Not a Valid TIFF File", getByteOrder());
