        }
    }
    if (planarConfiguration == TiffPlanarConfiguration.CHUNKY)
    {
        outDir.add(TiffTagConstants.TIFF_TAG_PLANAR_CONFIGURATION, (short) TiffTagConstants.PLANAR_CONFIGURATION_VALUE_CHUNKY);
    }
    else
