private boolean readDirectory(final ByteSource byteSource, final long directoryOffset, final int dirType, final FormatCompliance formatCompliance, final Listener listener, final boolean ignoreNextDirectory, final List<Number> visited) throws ImagingException, IOException  {
    if (visited.contains(directoryOffset))
    {
        return false;
    }
