    // verify that the file is a supported TIFF format using // the numeric indentifier // Classic TIFF (32 bit): 42 // Big TIFF (64 bit): 43 // final long offsetToFirstIFD;
    final int tiffVersion = BinaryFunctions.read2Bytes("tiffVersion", is, "Not a Valid TIFF File", getByteOrder());
