    final TiffField longitudeField = gpsDirectory.findField(GpsTagConstants.GPS_TAG_GPS_LONGITUDE);
    if (latitudeRefField == null || latitudeField == null || longitudeRefField == null || longitudeField == null)
    {
        return null;
