        standardTiff = false;
        entryMaxValueLength = ENTRY_MAX_VALUE_LENGTH_BIG;
        final int byteSize = BinaryFunctions.read2Bytes("bytesizeOfOffset", is, "Not a Valid TIFF File", getByteOrder());
