        // try ASCII, with NO prefix. final byte[] asciiBytes = s.getBytes(TEXT_ENCODING_ASCII.encodingName);
        final String decodedAscii = new String(asciiBytes, TEXT_ENCODING_ASCII.encodingName);
        if (decodedAscii.equals(s))
        {
            // no unicode/non-ascii values. final byte[] result = Allocator.byteArray(asciiBytes.length + TEXT_ENCODING_ASCII.prefix.length);
