            "code": "```java\nprivate void printWithQuotes(final Object object, final CharSequence charSeq, final Appendable out, final boolean newRecord) throws IOException  {\n    boolean quote = false;\n    int start = 0;\n    int pos = 0;\n    final int len = charSeq.length();\n    final char[] delim = getDelimiterCharArray();\n    final int delimLength = delim.length;\n    final char quoteChar = getQuoteCharacter().charValue();\n    // Explicit (un)boxing is intentional // If escape char not specified, default to the quote char // This avoids having to keep checking whether there is an escape character // at the cost of checking against quote twice final char escapeChar = isEscapeCharacterSet() ? getEscapeChar() : quoteChar;\n    QuoteMode quoteModePolicy = getQuoteMode();\n    if (quoteModePolicy == null)\n    {\n        quoteModePolicy = QuoteMode.MINIMAL;\n    }\n    switch (quoteModePolicy)\n    {\n        case ALL: case ALL_NON_NULL: quote = true;\n        break;\n        case NON_NUMERIC: quote = !(object instanceof Number);\n        break;\n        case NONE: // Use the existing escaping code printWithEscapes(charSeq, out);\n        return;\n        case MINIMAL: if (len <= 0)\n        {\n            // Always quote an empty token that is the first // on the line, as it may be the only thing on the // line. If it were not quoted in that case, // an empty line has no tokens. if (newRecord)\n            {\n                quote = true;\n            }\n        }\n        else\n        {\n            char c = charSeq.charAt(pos);\n            if (c <= Constants.COMMENT)\n            {\n                // Some other chars at the start of a value caused the parser to fail, so for now // encapsulate if we start in anything less than '#'. We are being conservative // by including the default comment char too. quote = true;\n            }\n            else\n            {\n                while (pos < len)\n                {\n                    c = charSeq.charAt(pos);\n                    if (c == Constants.LF || c == Constants.CR || c == quoteChar || c == escapeChar || isDelimiter(c, charSeq, pos, delim, delimLength))\n                    {\n                        quote = true;\n                        break;\n                    }\n                    pos++;\n                }\n                if (!quote)\n                {\n                    pos = len - 1;\n                    c = charSeq.charAt(pos);\n                    // Some other chars at the end caused the parser to fail, so for now // encapsulate if we end in anything less than ' ' if (isTrimChar(c))\n                    {\n                        quote = true;\n                    }\n                }\n            }\n        }\n        if (!quote)\n        {\n            // No encapsulation needed - write out the original value out.append(charSeq, start, len);\n            return;\n        }\n        break;\n        default: throw new IllegalStateException(\"Unexpected Quote value: \" + quoteModePolicy);\n    }\n    if (!quote)\n    {\n        // No encapsulation needed - write out the original value out.append(charSeq, start, len);\n        return;\n    }\n    // We hit something that needed encapsulation out.append(quoteChar);\n    // Pick up where we left off: pos should be positioned on the first character that caused // the need for encapsulation. while (pos < len)\n    {\n        final char c = charSeq.charAt(pos);\n        if (c == quoteChar || c == escapeChar)\n        {\n            // write out the chunk up until this point out.append(charSeq, start, pos);\n            out.append(escapeChar);\n            // now output the escape start = pos;\n            // and restart with the matched char\n        }\n        pos++;\n    }\n    // Write the last segment out.append(charSeq, start, pos);\n    out.append(quoteChar);\n}\n```"
