                TiffDirectoryConstants.DIRECTORY_TYPE_EXIF, TiffDirectoryConstants.DIRECTORY_TYPE_GPS, TiffDirectoryConstants.DIRECTORY_TYPE_INTEROPERABILITY
            }
            ;
            for (int i = 0;
            i < offsetFields.length;
            i++)
            {
                final TagInfoDirectory offsetField = offsetFields[i];
                final TiffField field = directory.findField(offsetField);
                if (field != null)
                {
                    final long subDirectoryOffset;
                    final int subDirectoryType;
                    boolean subDirectoryRead = false;
                    try
